__NUXT_JSONP__("/tw/about", (function(a){return {data:[{details:{slug:"tw",pageTitle:"什麼是MLI? | Mentor Language Institute",pageDescription:"Mentor Language Institute成立於2002年，位於兩個有名的地方: Westwood及Hollywood",section1:{title:"什麼是MLI?",description:["Mentor Language Institute成立於2002年，位於兩個有名的地方: Westwood及Hollywood，\u003Cbr \u002F\u003E我們幫助世界各地學生提升英語能力"]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"用更少的錢上有品質的課程",description:["我們重視兩件事情:  \u003Cb\u003E“教育的品質及價格”\u003Cb\u003E","英語是全球性的語言，是一個和來自世界各地的人溝通的必要工具。我們希望國際學生擁有英語能力，在世界上獲得成功。因此，我們著重於課程品質及低價位的課程。"]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"到2020年為止，超過17,000位學生選擇MLI並畢業於此。",description:["我們有ESL課程(一般英語課程包和六大項目: 文法\u002F寫作，閱讀\u002F單字及聽力\u002F口說)，TOEFL®, IELTS™ (預準備唸大專院校的學生), 和 TOEIC®。","許多學生繼續接著在美國各大專校唸書，像是UCLA，USC和 Santa Monica College。"],lists:[{link:"\u002Ftw\u002Ffeature",image:a,text:"選擇MLI的五個理由"},{link:"\u002Ftw\u002Fcompany",image:a,text:"機構資訊"},{link:"\u002Ftw\u002Fimage-gallery",image:a,text:"照片\u002F影片總覽"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:28.463Z",updatedAt:"2025-05-26T12:06:27.575Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));